(()=>{
const products=JSON.parse(document.getElementById('product-data').textContent);const cart=new Map();const money=n=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(n);const lines=document.getElementById('cart-lines');const totalEl=document.getElementById('total');const countEl=document.getElementById('cart-count');const status=document.getElementById('status');let category='Todos';
function render(){lines.replaceChildren();let total=0,count=0;for(const [id,quantity] of cart){const p=products.find(p=>p.id===id);total+=p.price*quantity;count+=quantity;const li=document.createElement('li');li.className='cart-line';const left=document.createElement('div');const name=document.createElement('strong');name.textContent=p.name;left.append(name,document.createElement('br'),document.createTextNode(money(p.price*quantity)));const right=document.createElement('div');right.className='quantity';const minus=document.createElement('button');minus.textContent='−';minus.type='button';minus.setAttribute('aria-label','Quitar uno: '+p.name);minus.onclick=()=>change(id,-1);const number=document.createElement('span');number.textContent=quantity;const plus=document.createElement('button');plus.textContent='+';plus.type='button';plus.setAttribute('aria-label','Añadir uno: '+p.name);plus.onclick=()=>change(id,1);right.append(minus,number,plus);li.append(left,right);lines.append(li);}document.getElementById('empty').hidden=cart.size>0;totalEl.textContent=money(total);countEl.textContent=count;return {items:[...cart].map(([id,quantity])=>({id,name:products.find(p=>p.id===id).name,quantity})),total,count};}
function change(id,delta){if(!products.some(p=>p.id===id))throw new Error('Producto no válido');const n=(cart.get(id)||0)+delta;if(n<=0)cart.delete(id);else cart.set(id,Math.min(n,20));status.textContent='';return render();}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{change(b.dataset.add,1);b.textContent='Añadido';setTimeout(()=>b.textContent='Añadir',900);});
function filter(value){const options=[...document.querySelectorAll('[data-filter]')].map(b=>b.dataset.filter);if(!options.includes(value))throw new Error('Categoría no válida');category=value;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===value)));document.querySelectorAll('[data-category]').forEach(card=>card.hidden=value!=='Todos'&&card.dataset.category!==value);return {category:value};}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>filter(b.dataset.filter));
document.getElementById('clear-cart').onclick=()=>{cart.clear();status.textContent='';render();};
document.getElementById('demo-checkout').onclick=()=>{const state=render();if(!state.count){status.textContent='Añade al menos un producto para probar el pedido.';return;}status.textContent='Simulación lista. No se ha enviado ningún pedido ni realizado un cobro.\n\n'+state.items.map(p=>p.quantity+' × '+p.name).join('\n')+'\nTotal de ejemplo: '+money(state.total);};
render();
})();
